ListNode* reverseList(ListNode* head) {
    ListNode *prev = nullptr, *curr = head;
    while(curr){
        ListNode* nxt = curr->next;
        curr->next = prev;
        prev = curr;
        curr = nxt;
    }
    return prev;
}

void reverseString(char* s, int sSize) {
    int l = 0, r = sSize - 1;
    while (l < r) {
        char tmp = s[l];
        s[l++] = s[r];
        s[r--] = tmp;
    }
}

bool hasCycle(struct ListNode *head) {
    if (!head || !head->next) return false;
    struct ListNode *slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return true;
    }
    return false;
}

int** allocateMatrix(int r, int c) {
    int** mat = (int**)malloc(r * sizeof(int*));
    if (!mat) return NULL;
    for (int i = 0; i < r; i++) {
        mat[i] = (int*)calloc(c, sizeof(int));
        if (!mat[i]) return NULL;
    }
    return mat;
}

def isPalindrome(s: str) -> bool:
    cleaned = [c.lower() for c in s if c.isalnum()]
    return cleaned == cleaned[::-1]

from collections import defaultdict
def groupAnagrams(strs):
    groups = defaultdict(list)
    for s in strs:
        groups[tuple(sorted(s))].append(s)
    return list(groups.values())

from collections import OrderedDict
class LRUCache:
    def __init__(self, capacity: int):
        self.cap = capacity
        self.cache = OrderedDict()
    def get(self, key: int) -> int:
        if key not in self.cache: return -1
        self.cache.move_to_end(key)
        return self.cache[key]
    def put(self, key: int, val: int) -> None:
        if key in self.cache: self.cache.move_to_end(key)
        self.cache[key] = val
        if len(self.cache) > self.cap: self.cache.popitem(last=False)

public boolean isValid(String s) {
    Stack<Character> st = new Stack<>();
    for (char c : s.toCharArray()) {
        if (c == '(') st.push(')');
        else if (c == '{') st.push('}');
        else if (c == '[') st.push(']');
        else if (st.isEmpty() || st.pop() != c) return false;
    }
    return st.isEmpty();
}

public List<List<Integer>> levelOrder(TreeNode root) {
    List<List<Integer>> res = new ArrayList<>();
    if (root == null) return res;
    Queue<TreeNode> q = new LinkedList<>();
    q.add(root);
    while (!q.isEmpty()) {
        int sz = q.size();
        List<Integer> lvl = new ArrayList<>();
        for (int i = 0; i < sz; i++) {
            TreeNode n = q.poll();
            lvl.add(n.val);
            if (n.left != null) q.add(n.left);
            if (n.right != null) q.add(n.right);
        }
        res.add(lvl);
    }
    return res;
}

class BoundedBuffer {
    final Lock lock = new ReentrantLock();
    final Condition notFull  = lock.newCondition();
    final Condition notEmpty = lock.newCondition();
    final Object[] items = new Object[100];
    int putptr, takeptr, count;
    public void put(Object x) throws InterruptedException {
        lock.lock();
        try {
            while (count == items.length) notFull.await();
            items[putptr] = x;
            if (++putptr == items.length) putptr = 0;
            ++count;
            notEmpty.signal();
        } finally { lock.unlock(); }
    }
}

function containsDuplicate(nums) {
    return new Set(nums).size !== nums.length;
}

function lengthOfLongestSubstring(s) {
    let map = new Map(), left = 0, max = 0;
    for (let right = 0; right < s.length; right++) {
        if (map.has(s[right])) left = Math.max(map.get(s[right]) + 1, left);
        map.set(s[right], right);
        max = Math.max(max, right - left + 1);
    }
    return max;
}

function promiseAll(promises) {
    return new Promise((resolve, reject) => {
        let results = [], resolvedCount = 0;
        if (promises.length === 0) return resolve(results);
        promises.forEach((p, index) => {
            Promise.resolve(p).then(val => {
                results[index] = val;
                resolvedCount++;
                if (resolvedCount === promises.length) resolve(results);
            }).catch(reject);
        });
    });
}

